    if depot is None:
        depot = 0

    capacity = get_key("capacity", "vehicle_capacity", "vehicleCapacity", "CAPACITY")
    if capacity is None:
        capacity = 0

    demands = get_key("demands", "demand")
    coords = get_key("coords", "coordinates", "locations", "nodes")
    dist_matrix = get_key("distance_matrix", "distances", "matrix")

    customers = get_key("customers", "customer_ids", "ids")
    if customers is None:
        customers = []
        try:
            for k in demands:
                if k != depot:
                    customers.append(k)
        except Exception:
            try:
                for k in coords:
                    if k != depot:
                        customers.append(k)
            except Exception:
                try:
                    n = instance["n"]
                except Exception:
                    try:
                        n = instance["num_customers"]
                    except Exception:
                        n = 0
                c = 1
                while c <= n:
                    customers.append(c)
                    c += 1

    def demand_of(i):
        try:
            return demands.get(i, 0)
        except Exception:
            pass
        try:
            if 0 <= i < len(demands):
                return demands[i]
        except Exception:
            pass
        return 0

    def coord_of(i):
        try:
            return coords.get(i)
        except Exception:
            pass
        try:
            if 0 <= i < len(coords):
                return coords[i]
        except Exception:
            pass
        return None

    def dist(i, j):
        try:
            return dist_matrix[i][j]
        except Exception:
            try:
                return dist_matrix[j][i]
            except Exception:
                pass
        ci = coord_of(i)
        cj = coord_of(j)
        try:
            if ci is not None and cj is not None and len(ci) >= 2 and len(cj) >= 2:
                dx = ci[0] - cj[0]
                dy = ci[1] - cj[1]
                return (dx * dx + dy * dy) ** 0.5
        except Exception:
            pass
        try:
            return abs(i - j)
        except Exception:
            return 0

    def route_load(route):
        s = 0
        for c in route:
            s += demand_of(c)
        return s

    def route_cost(route):
        if not route:
            return 0
        total = dist(depot, route[0])
        idx = 0
        while idx + 1 < len(route):
            total += dist(route[idx], route[idx + 1])
            idx += 1
        total += dist(route[-1], depot)
        return total

    def insertion_delta(route, pos, c):
        left = depot if pos == 0 else route[pos - 1]
        right = depot if pos == len(route) else route[pos]
        return dist(left, c) + dist(c, right) - dist(left, right)

    def normalize_routes(routes):
        out = []
        for r in routes:
            if r:
                out.append(r)
        return out

    # Initial greedy construction: nearest feasible insertion from depot-biased order.
    unserved = {}
    for c in customers:
        if c != depot:
            unserved[c] = True

    ordered = list(customers)
    ordered.sort(key=lambda c: (dist(depot, c), -demand_of(c), c))

    routes = []
    while unserved:
        start = None
        bestk = None
        for c in ordered:
            if c in unserved:
                k = (dist(depot, c), -demand_of(c), c)
                if bestk is None or k < bestk:
                    bestk = k
                    start = c
        if start is None:
            break
        route = [start]
        del unserved[start]
        load = demand_of(start)
        last = start
        while True:
            best = None
            bestk = None
            for c in ordered:
                if c not in unserved:
                    continue
                d = demand_of(c)
                if load + d > capacity:
                    continue
                k = (dist(last, c), dist(depot, c), -d, c)
                if bestk is None or k < bestk:
                    bestk = k
                    best = c
            if best is None:
                break
            route.append(best)
            del unserved[best]
            load += demand_of(best)
            last = best
        routes.append(route)

    # Repair: insert any missing customers into best feasible position or new route.
    if unserved:
        remaining = list(unserved.keys())
        for c in remaining:
            best_r = -1
            best_p = -1
            best_delta = None
            for r_idx in range(len(routes)):
                r = routes[r_idx]
                if route_load(r) + demand_of(c) > capacity:
                    continue
                p = 0
                while p <= len(r):
                    delta = insertion_delta(r, p, c)
                    if best_delta is None or delta < best_delta or (delta == best_delta and (r_idx, p, c) < (best_r, best_p, c)):
                        best_delta = delta
                        best_r = r_idx
                        best_p = p
                    p += 1
            if best_r >= 0:
                routes[best_r].insert(best_p, c)
            else:
                routes.append([c])
            try:
                del unserved[c]
            except Exception:
                pass

    routes = normalize_routes(routes)

    # Capacity-aware 2-opt inside routes and relocate between routes.
    improved = True
    outer = 0
    while improved and outer < 3:
        improved = False
        outer += 1

        # Intra-route 2-opt.
        for r_idx in range(len(routes)):
            r = routes[r_idx]
            n = len(r)
            changed = True
            guard = 0
            while changed and guard < 20:
                changed = False
                guard += 1
                i = 0
                while i + 2 < n:
                    k = i + 1
                    while k + 1 < n:
                        a = depot if i < 0 else (depot if i == -1 else r[i])
                        b = r[i + 1]
                        c = r[k]
                        d = depot if k + 1 >= n else r[k + 1]
                        before = dist(a, b) + dist(c, d)
                        after = dist(a, c) + dist(b, d)
                        if after + 1e-12 < before:
                            r[i + 1:k + 1] = r[i + 1:k + 1][::-1]
                            changed = True
                            improved = True
                            break
                        k += 1
                    if changed:
                        break
                    i += 1
            routes[r_idx] = r

        # Inter-route relocate.
        i = 0
        while i < len(routes):
            j = 0
            while j < len(routes):
                if i != j and i < len(routes) and j < len(routes):
                    ri = routes[i]
                    rj = routes[j]
                    moved = False
                    a = 0
                    while a < len(ri):
                        c = ri[a]
                        dc = demand_of(c)
                        if route_load(rj) + dc <= capacity:
                            best_delta = None
                            best_pos = None
                            base_remove = 0
                            if len(ri) == 1:
                                base_remove = dist(depot, c) + dist(c, depot)
                            else:
                                prevc = depot if a == 0 else ri[a - 1]
                                nextc = depot if a == len(ri) - 1 else ri[a + 1]
                                base_remove = dist(prevc, c) + dist(c, nextc) - dist(prevc, nextc)
                            p = 0
                            while p <= len(rj):
                                delta_ins = insertion_delta(rj, p, c)
                                delta = delta_ins - base_remove
                                if best_delta is None or delta < best_delta:
                                    best_delta = delta
                                    best_pos = p
                                p += 1
                            if best_delta is not None and best_delta < -1e-12:
                                del ri[a]
                                rj.insert(best_pos, c)
                                moved = True
                                improved = True
                                break
                        a += 1
                    routes[i] = ri
                    routes[j] = rj
                    if moved:
                        if len(routes[i]) == 0:
                            del routes[i]
                            if j > i:
                                j -= 1
                            break
                j += 1
            if i < len(routes):
                i += 1

    routes = normalize_routes(routes)

    # Final guarantee: every customer exactly once.
    seen = {}
    out = []
    for r in routes:
        nr = []
        for c in r:
            if c != depot and c not in seen:
                seen[c] = True
                nr.append(c)
        if nr:
            out.append(nr)

    missing = []
    for c in customers:
        if c != depot and c not in seen:
            missing.append(c)

    for c in missing:
        best_r = -1
        best_p = -1
        best_delta = None
        for r_idx in range(len(out)):
            r = out[r_idx]
            if route_load(r) + demand_of(c) > capacity:
                continue
            p = 0
            while p <= len(r):
                delta = insertion_delta(r, p, c)
                if best_delta is None or delta < best_delta:
                    best_delta = delta
                    best_r = r_idx
                    best_p = p
                p += 1
        if best_r >= 0:
            out[best_r].insert(best_p, c)
        else:
            out.append([c])

    return out
